package blame.blamegen;

import io.github.opencubicchunks.cubicchunks.api.util.IntRange;
import io.github.opencubicchunks.cubicchunks.api.world.ICubicWorld;
import io.github.opencubicchunks.cubicchunks.api.world.ICubicWorldType;
import io.github.opencubicchunks.cubicchunks.api.worldgen.ICubeGenerator;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.World;
import net.minecraft.world.WorldServer;
import net.minecraft.world.WorldType;

/**
 * "BLAME" world type: a CubicChunks world whose overworld is generated by the megastructure
 * generator. Other dimensions keep their vanilla generators.
 */
public class BlameWorldType extends WorldType implements ICubicWorldType {

    public static final String NAME = "BLAME";

    public BlameWorldType() {
        super(NAME);
    }

    @Override
    public ICubeGenerator createCubeGenerator(World world) {
        return new BlameCubeGenerator(world);
    }

    @Override
    public IntRange calculateGenerationHeightRange(WorldServer world) {
        ICubicWorld cw = (ICubicWorld) world;
        return new IntRange(cw.getMinHeight(), cw.getMaxHeight());
    }

    @Override
    public boolean hasCubicGeneratorForWorld(World world) {
        return world.provider.getDimension() == 0;
    }

    @Override
    public float getCloudHeight() {
        return 2400.0F;
    }

    @Override
    public int getSpawnFuzz(WorldServer world, MinecraftServer server) {
        return 0;
    }

    @Override
    public boolean hasInfoNotice() {
        return true;
    }
}
